entries.syntax_block:
// модуль роли
Procedure OnAccessRead(Source, Operation, Allowed)
{
    Source = Source.Where(Function(x) { Return x.Code = "13"; });
    Allowed = True;
}

entries.syntax_block_ves:
// модуль роли
Procedure OnAccessRead(Source, Operation, Allowed)
    Source = Source.Where(Function(x) Return x.Code = "13"; EndFunction);
    Allowed = True;
EndProcedure

entries.example:
// отбор по текущему пользователю через регистр доступа
Procedure OnAccessRead(Source, Operation, Allowed)
{
    if (Source = "Catalog.Товары") {
        Source = restrict s in Source
                     join a in Data.Registers.ДоступКСкладам.Where(Function(a) { Return a.Пользователь = CurrentUser(); })
                         on s.Склад = a.Склад;
    }
    Allowed = True;
}

