// разыменование через точку работает: платформа сама построит соединение
Procedure OnAccessRead(Source, Operation, Allowed)
{
    if (Source = "Document.Расходная") {
        Source = Source.Where(Function(x) { Return x.Договор.Организация = ТекущаяОрганизация(); });
    }
    Allowed = True;
}

entries.syntax_block:
Procedure OnAccessWrite(Source, Operation, Allowed)
{
    if (Source = "Catalog.Товары") {
        if (Operation = "Delete") {
            Allowed = False;
            Return;
        }
        Source = Source.Where(Function(x) { Return x.Склад = ТекущийСклад(); });
    }
    Allowed = True;
}

